import{_ as n,a0 as l,w as a,s as p,ao as d,I as o,x as t,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"10个开源的基于WEB的文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"10个开源的基于WEB的文件管理器 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10个开源的基于WEB的文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10个开源的基于WEB的文件管理器 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/10 Useful Open Source Web Based File Managers","title":"10个开源的基于WEB的文件管理器","tag":"201402","desc":""},"relativePath":"201402/10 Useful Open Source Web Based File Managers.md","filePath":"[post].md"}'),g={name:"201402/10 Useful Open Source Web Based File Managers.md"};function u(m,e,f,P,T,C){const r=l("Link");return a(),p("div",null,[e[11]||(e[11]=d('<h1 id="_10个开源的基于web的文件管理器" tabindex="-1">10个开源的基于WEB的文件管理器 <a class="header-anchor" href="#_10个开源的基于web的文件管理器" aria-label="Permalink to “10个开源的基于WEB的文件管理器”">​</a></h1><p>目前，随着因特网的广泛普及，对文件管理的需求变得更多。对很多人来说，用一个应用程序来有效管理你在网络上的文件是必不可少的。因此，下面列出你会用到的10个最好的开源的基于WEB的文件管理器。</p><p><img src="http://www.efytimes.com/admin/useradmin/photo/xBds51300PM1102014.jpg" alt=""></p><ol><li><p><strong>eXtplorer</strong>: 这个程序为你提供了移动、复制、编辑、搜索、删除、下载和上传功能。此外，你也能用 eXtplorer 创建和提取档案，文件夹和新文件。它的主要功能是让你通过 FTP 访问文件。你可以选择 Mozilla 公共许可或者 GPL 协议。为了正常使用这个文件管理器，服务器的PHP最低版本要求为 PHP 4.3 并且必须更新JavaScript。</p></li><li><p><strong>AjaXplorer</strong>: 绝大多数浏览器都支持这个文件管理器，并且它能很轻易地自动适应类似于手机一样的小屏幕浏览。目前iOS版的程序已经被开发出来了，安卓版的也将很快完成。要运行 AjaXplorer:，你所需要的是一个支持 PHP5.1 或者更高版本的WEB服务器来。它允许你直接从服务器流式传输视频内容。</p></li><li><p><strong>KFM</strong>: 这个免费和开源文件管理器可以作为 FCKedition、CKeditor、Tiny MCE 之类的富文本编辑器的插件。如果您正在使用一个基于 Linux 的操作系统，那么你需要 PHP 5.2 或更高版本，而 Mac OS X 和 Windows 分别需要 MySQL 4.1 或更高版本和 MySQL 5.0 或更高版本。它有一个自己的搜索引擎，附带了一个文本编辑器，可以高亮显示语法。它还带有 mp3 播放和视频播放选项。</p></li><li><p><strong>PAFM</strong>: 这个文件管理器可以让用户完全控制文件，还允许使用 CodePress 来编辑源代码。文件管理器的主要特色来自 CodePress，它提供了即时的语法高亮显示。</p></li><li><p><strong>QuiXplorer</strong>: 这个文件管理器可用于在互联网和局域网管理和共享文件。它还提供了一种多用户模式，每个用户可以定制自己的设置。</p></li><li><p><strong>BytesFall</strong> Explorer: 这个使用 PHP 和 JavaScript 编写的管理器在 GPL 下发布。它的 UI 非常类似于 Windows 资源管理器，但是它被用在 GeSHi、LiveTree、Shell 命令、FCKeditor 等项目。因为它有一组不同的功能。</p></li><li><p><strong>NavPHP</strong>: 这个文件管理器是使用PHP和AJAX编写的，并且提供了WindowsXP风格的导航。和 QuiXplorer 一样，这个管理器也有一个多用户模式，并有自己的代码编辑器。此外，它还可以使用Deflate和Gzip来压缩传输网页。你也可以使用这个功能来以zip格式下载文件或文件夹。</p></li><li><p><strong>iDC File Manager</strong>: 这是一个多用户系统，可以安装在基于 Linux 或 Windows 的网页服务器上。它提供了热键功能并支持社交网络，还可以监视用户活动。它的数据库是 MySQL。</p></li><li><p><strong>FileMan</strong>: 这个文件管理器带有一个所见即所得编辑器，可以编辑和创建 HTML 文件。除了 HTML 编辑器,它还具有其他很多有用的功能。</p></li><li><p><strong>Relay</strong>: 这个文件管理器使用 GPL 协议发布，并支持 AJAX。如果你使用大量的目录和文件,那么这个管理器对你来说非常理想。</p></li></ol><hr>',5)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),s(r,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=126569"},{default:i(()=>[...e[0]||(e[0]=[t("http://www.efytimes.com/e1/fullnews.asp?edid=126569",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("译者：",-1)),s(r,{href:"https://github.com/kingname"},{default:i(()=>[...e[2]||(e[2]=[t("kingname",-1)])]),_:1}),e[5]||(e[5]=t(" 校对：",-1)),s(r,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...e[3]||(e[3]=[t("Caroline",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原创翻译，",-1)),s(r,{href:"http://linux.cn/"},{default:i(()=>[...e[7]||(e[7]=[t("Linux中国",-1)])]),_:1}),e[10]||(e[10]=t(" 荣誉推出",-1))])])}const B=n(g,[["render",u]]);export{w as __pageData,B as default};
